contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value,
                "test contract must be able to receive value Ether");
        require(address(c).balance >= value,
                "precondition: c holds at least value Ether");

        uint beforeBal = address(c).balance;
        uint beforeOwnerBal = address(this).balance;

        c.withdraw(value); if (__ESBMC_reverted()) return;

        uint afterBal = address(c).balance;
        uint afterOwnerBal = address(this).balance;

        assert(afterBal == beforeBal - value
            && afterOwnerBal == beforeOwnerBal + value);
    }

    receive() external payable {}
}

