// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        vm.assume(address(c).balance >= value);
        uint beforeBal = address(c).balance;
        uint beforeOwnerBal = address(this).balance;
        try c.withdraw(value) {} catch { return; }
        uint afterBal = address(c).balance;
        uint afterOwnerBal = address(this).balance;
        assertTrue(afterBal == beforeBal - value
            && afterOwnerBal == beforeOwnerBal + value);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
